CREATE TABLE IF NOT EXISTS users (
  id BIGSERIAL PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password_hash TEXT NOT NULL, display_name VARCHAR(100) NOT NULL, phone VARCHAR(32),
  role VARCHAR(16) NOT NULL CHECK (role IN ('admin','user')), status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  profile JSONB NOT NULL DEFAULT '{}'::jsonb, last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, ip VARCHAR(128), user_agent TEXT, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS maps (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, owner_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')), cover_path TEXT, description TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS map_permissions (map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, permissions TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], granted_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (map_id,user_id));
CREATE INDEX IF NOT EXISTS idx_map_permissions_user ON map_permissions(user_id);
CREATE TABLE IF NOT EXISTS map_configs (map_id BIGINT PRIMARY KEY REFERENCES maps(id) ON DELETE CASCADE, config JSONB NOT NULL DEFAULT '{"ranks":[],"gifts":[],"anchorGifts":[],"globals":[],"dayLimits":[],"randomGroups":[],"preloadCode":""}'::jsonb, updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS players (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, uid VARCHAR(128) NOT NULL, name VARCHAR(160) NOT NULL, level INTEGER NOT NULL DEFAULT 0 CHECK (level>=0), game_level VARCHAR(32) NOT NULL DEFAULT '', item_ban BOOLEAN NOT NULL DEFAULT FALSE, data_ban BOOLEAN NOT NULL DEFAULT FALSE, rank_ban BOOLEAN NOT NULL DEFAULT FALSE, profile JSONB NOT NULL DEFAULT '{}'::jsonb, last_active_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,uid));
CREATE INDEX IF NOT EXISTS idx_players_map_name ON players(map_id,name);
CREATE INDEX IF NOT EXISTS idx_players_map_active ON players(map_id,last_active_at DESC);
CREATE TABLE IF NOT EXISTS gifts (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, gift_key VARCHAR(128) NOT NULL, name VARCHAR(160) NOT NULL, description TEXT NOT NULL DEFAULT '', default_value NUMERIC(18,4) NOT NULL DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,gift_key));
CREATE TABLE IF NOT EXISTS gift_entitlements (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, gift_id BIGINT NOT NULL REFERENCES gifts(id) ON DELETE CASCADE, player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE, value NUMERIC(18,4) NOT NULL CHECK(value>0), updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,player_id,gift_id));
CREATE INDEX IF NOT EXISTS idx_gift_entitlements_map_player ON gift_entitlements(map_id,player_id);
CREATE TABLE IF NOT EXISTS anchors (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, gift_config JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,name));
CREATE TABLE IF NOT EXISTS tracking_points (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, point_key VARCHAR(128) NOT NULL, name VARCHAR(160) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, trigger_count BIGINT NOT NULL DEFAULT 0 CHECK(trigger_count>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,point_key));
CREATE TABLE IF NOT EXISTS map_logs (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, context TEXT NOT NULL, player_count BIGINT NOT NULL DEFAULT 0, upload_count BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,context));
CREATE INDEX IF NOT EXISTS idx_map_logs_map_time ON map_logs(map_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS map_files (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, kind VARCHAR(16) NOT NULL DEFAULT 'file' CHECK(kind IN ('file','folder')), original_name VARCHAR(255) NOT NULL, storage_name VARCHAR(255), relative_path TEXT NOT NULL, mime_type VARCHAR(160), size_bytes BIGINT NOT NULL DEFAULT 0 CHECK(size_bytes>=0), sha256 CHAR(64), uploaded_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,relative_path));
CREATE INDEX IF NOT EXISTS idx_map_files_parent ON map_files(map_id,relative_path);
CREATE TABLE IF NOT EXISTS map_metrics (map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, metric_date DATE NOT NULL, cumulative_users BIGINT NOT NULL DEFAULT 0, online_users BIGINT NOT NULL DEFAULT 0, total_game_count BIGINT NOT NULL DEFAULT 0, daily_new_users BIGINT NOT NULL DEFAULT 0, daily_active_users BIGINT NOT NULL DEFAULT 0, lost_user_count BIGINT NOT NULL DEFAULT 0, return_user_count BIGINT NOT NULL DEFAULT 0, active_user_retention_rate NUMERIC(8,4) NOT NULL DEFAULT 0, new_user_retention_rate NUMERIC(8,4) NOT NULL DEFAULT 0, seven_day_retention_rate NUMERIC(8,4) NOT NULL DEFAULT 0, replay_rate NUMERIC(8,4) NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(map_id,metric_date));
CREATE TABLE IF NOT EXISTS api_keys (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, token_prefix VARCHAR(16) NOT NULL, token_ciphertext TEXT, permissions TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), last_used_at TIMESTAMPTZ, created_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_api_keys_map ON api_keys(map_id);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, action VARCHAR(120) NOT NULL, resource_type VARCHAR(80) NOT NULL, resource_id VARCHAR(128), map_id BIGINT REFERENCES maps(id) ON DELETE SET NULL, ip VARCHAR(128), user_agent TEXT, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_audit_logs_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_actor ON audit_logs(actor_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_map ON audit_logs(map_id,created_at DESC);
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(120) PRIMARY KEY, value JSONB NOT NULL, updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS player_messages (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, player_id BIGINT NOT NULL REFERENCES players(id) ON DELETE CASCADE, subject VARCHAR(160) NOT NULL, content TEXT NOT NULL, attachments JSONB NOT NULL DEFAULT '[]'::jsonb, status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','delivered')), created_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), delivered_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_player_messages_pending ON player_messages(map_id,player_id,status,created_at);
CREATE TABLE IF NOT EXISTS lottery_campaigns (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, public_token VARCHAR(96) NOT NULL UNIQUE, title VARCHAR(160) NOT NULL, description TEXT NOT NULL DEFAULT '', status VARCHAR(16) NOT NULL DEFAULT 'open' CHECK(status IN ('open','drawn','cancelled')), draw_at TIMESTAMPTZ, winner_count INTEGER NOT NULL DEFAULT 1 CHECK(winner_count BETWEEN 1 AND 100), reward_config JSONB NOT NULL DEFAULT '[]'::jsonb, created_by BIGINT REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), drawn_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_lottery_campaigns_map ON lottery_campaigns(map_id,created_at DESC);
CREATE TABLE IF NOT EXISTS lottery_entries (id BIGSERIAL PRIMARY KEY, campaign_id BIGINT NOT NULL REFERENCES lottery_campaigns(id) ON DELETE CASCADE, participant_key VARCHAR(160) NOT NULL, player_name VARCHAR(160) NOT NULL, player_uid VARCHAR(128), contact VARCHAR(160), is_winner BOOLEAN NOT NULL DEFAULT FALSE, ip VARCHAR(128), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(campaign_id,participant_key));
CREATE INDEX IF NOT EXISTS idx_lottery_entries_campaign ON lottery_entries(campaign_id,created_at);
CREATE TABLE IF NOT EXISTS leaderboards (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, leaderboard_key VARCHAR(128) NOT NULL, name VARCHAR(160) NOT NULL, value_label VARCHAR(80) NOT NULL DEFAULT '积分', sort_direction VARCHAR(4) NOT NULL DEFAULT 'desc' CHECK(sort_direction IN ('asc','desc')), score_update_mode VARCHAR(16) NOT NULL DEFAULT 'latest' CHECK(score_update_mode IN ('latest','best')), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,leaderboard_key));
CREATE INDEX IF NOT EXISTS idx_leaderboards_map ON leaderboards(map_id,created_at);
CREATE TABLE IF NOT EXISTS leaderboard_entries (id BIGSERIAL PRIMARY KEY, leaderboard_id BIGINT NOT NULL REFERENCES leaderboards(id) ON DELETE CASCADE, player_uid VARCHAR(128) NOT NULL, player_name VARCHAR(160) NOT NULL, game_level VARCHAR(64) NOT NULL DEFAULT '', score NUMERIC(30,6) NOT NULL DEFAULT 0, game_count BIGINT NOT NULL DEFAULT 0 CHECK(game_count>=0), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, last_submitted_on DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(leaderboard_id,player_uid));
CREATE INDEX IF NOT EXISTS idx_leaderboard_entries_rank ON leaderboard_entries(leaderboard_id,score,updated_at DESC);
CREATE TABLE IF NOT EXISTS leaderboard_snapshots (id BIGSERIAL PRIMARY KEY, leaderboard_id BIGINT NOT NULL REFERENCES leaderboards(id) ON DELETE CASCADE, entry_count INTEGER NOT NULL DEFAULT 0 CHECK(entry_count>=0), published_by BIGINT REFERENCES users(id) ON DELETE SET NULL, published_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_leaderboard_snapshots_latest ON leaderboard_snapshots(leaderboard_id,published_at DESC);
CREATE TABLE IF NOT EXISTS leaderboard_snapshot_entries (snapshot_id BIGINT NOT NULL REFERENCES leaderboard_snapshots(id) ON DELETE CASCADE, rank INTEGER NOT NULL CHECK(rank>0), player_uid VARCHAR(128) NOT NULL, player_name VARCHAR(160) NOT NULL, game_level VARCHAR(64) NOT NULL DEFAULT '', score NUMERIC(30,6) NOT NULL, game_count BIGINT NOT NULL DEFAULT 0 CHECK(game_count>=0), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, achieved_at TIMESTAMPTZ, PRIMARY KEY(snapshot_id,rank), UNIQUE(snapshot_id,player_uid));
CREATE TABLE IF NOT EXISTS risk_rules (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, rule_key VARCHAR(128) NOT NULL, name VARCHAR(160) NOT NULL, severity VARCHAR(16) NOT NULL DEFAULT 'medium' CHECK(severity IN ('low','medium','high','critical')), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,rule_key));
CREATE INDEX IF NOT EXISTS idx_risk_rules_map ON risk_rules(map_id,created_at);
CREATE TABLE IF NOT EXISTS risk_events (id BIGSERIAL PRIMARY KEY, map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, event_key VARCHAR(128) NOT NULL, rule_id BIGINT REFERENCES risk_rules(id) ON DELETE SET NULL, rule_key VARCHAR(128) NOT NULL, rule_name VARCHAR(160) NOT NULL, severity VARCHAR(16) NOT NULL CHECK(severity IN ('low','medium','high','critical')), player_uid VARCHAR(128) NOT NULL, player_name VARCHAR(160) NOT NULL, occurrence_count INTEGER NOT NULL DEFAULT 1 CHECK(occurrence_count>0), status VARCHAR(16) NOT NULL DEFAULT 'open' CHECK(status IN ('open','reviewed','blocked','ignored')), details JSONB NOT NULL DEFAULT '{}'::jsonb, occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), handled_by BIGINT REFERENCES users(id) ON DELETE SET NULL, handled_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(map_id,event_key));
CREATE INDEX IF NOT EXISTS idx_risk_events_queue ON risk_events(map_id,status,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_risk_events_player ON risk_events(map_id,player_uid,occurred_at DESC);
CREATE TABLE IF NOT EXISTS fq_player_archives (map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, player_uid VARCHAR(128) NOT NULL, archive_data JSONB NOT NULL DEFAULT '{}'::jsonb, revision BIGINT NOT NULL DEFAULT 0 CHECK(revision>=0), last_request_id VARCHAR(128), last_request_hash CHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(map_id,player_uid), CHECK((last_request_id IS NULL AND last_request_hash IS NULL) OR (last_request_id IS NOT NULL AND last_request_hash IS NOT NULL)), CHECK(jsonb_typeof(archive_data)='object'));
CREATE INDEX IF NOT EXISTS idx_fq_player_archives_updated ON fq_player_archives(map_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS fq_global_archives (map_id BIGINT PRIMARY KEY REFERENCES maps(id) ON DELETE CASCADE, archive_data JSONB NOT NULL DEFAULT '{}'::jsonb, revision BIGINT NOT NULL DEFAULT 0 CHECK(revision>=0), last_request_id VARCHAR(128), last_request_hash CHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK((last_request_id IS NULL AND last_request_hash IS NULL) OR (last_request_id IS NOT NULL AND last_request_hash IS NOT NULL)), CHECK(jsonb_typeof(archive_data)='object'));
CREATE TABLE IF NOT EXISTS fq_metric_sessions (map_id BIGINT NOT NULL REFERENCES maps(id) ON DELETE CASCADE, session_id TEXT NOT NULL CHECK(char_length(session_id) BETWEEN 1 AND 512), started_at TIMESTAMPTZ NOT NULL, last_heartbeat_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(map_id,session_id));
CREATE INDEX IF NOT EXISTS idx_fq_metric_sessions_started ON fq_metric_sessions(map_id,started_at);
CREATE INDEX IF NOT EXISTS idx_fq_metric_sessions_online ON fq_metric_sessions(map_id,last_heartbeat_at DESC) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS fq_metric_session_activity (map_id BIGINT NOT NULL, session_id TEXT NOT NULL, player_uid VARCHAR(128) NOT NULL, active_date DATE NOT NULL, first_seen_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(map_id,session_id,player_uid,active_date), FOREIGN KEY(map_id,session_id) REFERENCES fq_metric_sessions(map_id,session_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_fq_metric_activity_day_uid ON fq_metric_session_activity(map_id,active_date,player_uid);
CREATE INDEX IF NOT EXISTS idx_fq_metric_activity_uid_day ON fq_metric_session_activity(map_id,player_uid,active_date);
CREATE INDEX IF NOT EXISTS idx_fq_metric_activity_online ON fq_metric_session_activity(map_id,active_date,last_seen_at DESC);
